window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-324ca3bd37a7ef6b"]={"versions": [{"id": "FIG-324ca3bd37a7ef6b", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Software-Systemkonstanten im Rahmen des AUTOSAR Generic Structure Template (Paket <code>SystemConstant</code> und <code>DataDefProperties</code>). Es modelliert die Struktur der Metaklasse <code>SwSystemconst</code> und deren Eigenschaften über aggregierte Daten-Definitionseigenschaften.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei primäre Modellelemente:</p>\n<ul class=\"fig-list\"><li><strong><code>SystemConstant::SwSystemconst</code></strong>: Metaklasse mit dem Spezialisierungs-/Stereotyphinweis <code>ARElement</code>. Sie fungiert als Wurzel- bzw. Definitionselement für Systemkonstanten.\n</li><li><strong><code>«atpVariation» DataDefProperties::SwDataDefProps</code></strong>: Metaklasse zur Kapselung von Software-Daten-Eigenschaften, versehen mit dem Stereotyp <code>«atpVariation»</code>.\n</li><li><strong>Assoziation / Komposition</strong>: <code>SwSystemconst</code> aggregiert über eine gerichtete Komposition (ausgefüllte Raute bei <code>SwSystemconst</code>) das Rollenende <code>+swDataDefProps</code> mit der Kardinalität <code>0..1</code> vom Typ <code>SwDataDefProps</code>.\n</li></ul>\n<p class=\"fig-p\">Attribute von <code>DataDefProperties::SwDataDefProps</code>:</p>\n<ul class=\"fig-list\"><li><code>+ additionalNativeTypeQualifier: NativeDeclarationString [0..1]</code>\n</li><li><code>+ displayFormat: DisplayFormatString [0..1]</code>\n</li><li><code>+ mcFunction: Identifier [0..1]</code>\n</li><li><code>+ swAlignment: AlignmentType [0..1]</code>\n</li><li><code>+ swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code>\n</li><li><code>+ swImplPolicy: SwImplPolicyEnum [0..1]</code>\n</li><li><code>+ swIntendedResolution: Numerical [0..1]</code>\n</li><li><code>+ swInterpolationMethod: Identifier [0..1]</code>\n</li><li><code>+ swIsVirtual: Boolean [0..1]</code>\n</li><li>In einem gesonderten Variantenbereich (<code>«atpVariation»</code>): <code>+ swValueBlockSize: Numerical [0..1]</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Definition ohne dynamische Ablauf- oder Interaktionsdarstellung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Deklaration von <code>SwSystemconst</code> als <code>ARElement</code> weist die Klasse als eigenständiges, im AR-Package-Baum referenzierbares Modellierungselement aus. Die optionale Komposition <code>+swDataDefProps</code> (<code>0..1</code>) erlaubt die Zuweisung generischer Software-Dateneigenschaften. Das Stereotyp <code>«atpVariation»</code> an <code>SwDataDefProps</code> sowie am Attribut <code>swValueBlockSize</code> kennzeichnet die Unterstützung von AUTOSAR-Variabilität (Variant Handling) zur Build- oder Nachbearbeitungszeit. Alle Attribute innerhalb von <code>SwDataDefProps</code> sind optional mit Kardinalität <code>[0..1]</code> modelliert.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e643584321097067", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Software-Systemkonstanten im AUTOSAR Generic Structure Template. Es modelliert die Metaklasse <code>SwSystemconst</code> und deren Verbindung zu <code>SwDataDefProps</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Modellelemente:</p>\n<ul class=\"fig-list\"><li><strong><code>SwSystemconst</code></strong>: Metaklasse, ausgewiesen mit den Merkmalen <code>ARElement</code> und <code>AtpDefinition</code>.\n</li><li><strong><code>«atpVariation» SwDataDefProps</code></strong>: Metaklasse zur Spezifikation von Software-Dateneigenschaften unter dem Stereotyp <code>«atpVariation»</code>.\n</li><li><strong>Komposition</strong>: <code>SwSystemconst</code> aggregiert per Komposition das Rollenende <code>+swDataDefProps</code> mit Kardinalität <code>0..1</code> zu <code>SwDataDefProps</code>.\n</li></ul>\n<p class=\"fig-p\">Attribute von <code>SwDataDefProps</code>:</p>\n<ul class=\"fig-list\"><li><code>+ additionalNativeTypeQualifier :NativeDeclarationString [0..1]</code>\n</li><li><code>+ displayFormat :DisplayFormatString [0..1]</code>\n</li><li><code>+ mcFunction :Identifier [0..1]</code>\n</li><li><code>+ swAlignment :AlignmentType [0..1]</code>\n</li><li><code>+ swCalibrationAccess :SwCalibrationAccessEnum [0..1]</code>\n</li><li><code>+ swImplPolicy :SwImplPolicyEnum [0..1]</code>\n</li><li><code>+ swIntendedResolution :Numerical [0..1]</code>\n</li><li><code>+ swInterpolationMethod :Identifier [0..1]</code>\n</li><li><code>+ swIsVirtual :Boolean [0..1]</code>\n</li><li>Im Variantenbereich (<code>«atpVariation»</code>): <code>+ swValueBlockSize :Numerical [0..1]</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Definition ohne dynamische Ablauf- oder Interaktionsdarstellung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassifikation als <code>ARElement</code> und <code>AtpDefinition</code> kennzeichnet <code>SwSystemconst</code> als paketierbares Element mit Definitionssemantik im Rahmen des AUTOSAR Template Profile. Durch <code>«atpVariation»</code> an <code>SwDataDefProps</code> und an <code>swValueBlockSize</code> unterliegt die Zuordnung bzw. Ausprägung der Variabilitätsmechanik von AUTOSAR. Alle Eigenschaften von <code>SwDataDefProps</code> sind mit Kardinalität <code>[0..1]</code> optional gehalten.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f296eb605c1e4cad", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Software-Systemkonstanten im AUTOSAR Generic Structure Template. Es modelliert die Metaklasse <code>SwSystemconst</code> und deren Verbindung zu <code>SwDataDefProps</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Modellelemente:</p>\n<ul class=\"fig-list\"><li><strong><code>SwSystemconst</code></strong>: Metaklasse mit Kennzeichnung als <code>ARElement</code> und <code>AtpDefinition</code>.\n</li><li><strong><code>«atpVariation» SwDataDefProps</code></strong>: Metaklasse für Daten-Definitionseigenschaften unter dem Stereotyp <code>«atpVariation»</code>.\n</li><li><strong>Komposition</strong>: <code>SwSystemconst</code> aggregiert per Komposition das Rollenende <code>+swDataDefProps</code> mit Multiplizität <code>0..1</code> vom Typ <code>SwDataDefProps</code>.\n</li></ul>\n<p class=\"fig-p\">Attribute von <code>SwDataDefProps</code>:</p>\n<ul class=\"fig-list\"><li><code>+ additionalNativeTypeQualifier :NativeDeclarationString [0..1]</code>\n</li><li><code>+ displayFormat :DisplayFormatString [0..1]</code>\n</li><li><code>+ stepSize :Float [0..1]</code>\n</li><li><code>+ swAlignment :AlignmentType [0..1]</code>\n</li><li><code>+ swCalibrationAccess :SwCalibrationAccessEnum [0..1]</code>\n</li><li><code>+ swImplPolicy :SwImplPolicyEnum [0..1]</code>\n</li><li><code>+ swIntendedResolution :Numerical [0..1]</code>\n</li><li><code>+ swInterpolationMethod :Identifier [0..1]</code>\n</li><li><code>+ swIsVirtual :Boolean [0..1]</code>\n</li><li>Im Variantenbereich (<code>«atpVariation»</code>): <code>+ swValueBlockSize :Numerical [0..1]</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Definition ohne dynamische Ablauf- oder Interaktionsdarstellung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassifikation als <code>ARElement</code> und <code>AtpDefinition</code> kennzeichnet <code>SwSystemconst</code> als paketierbares Element mit Definitionssemantik im Rahmen des AUTOSAR Template Profile. Durch <code>«atpVariation»</code> an <code>SwDataDefProps</code> und an <code>swValueBlockSize</code> unterliegt die Zuordnung bzw. Ausprägung der Variabilitätsmechanik von AUTOSAR. Alle Eigenschaften von <code>SwDataDefProps</code> sind mit Kardinalität <code>[0..1]</code> optional gehalten.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-324ca3bd37a7ef6b", "to": "FIG-e643584321097067", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>SwSystemconst</code>: Paketpräfix <code>SystemConstant::</code> im Klassennamen entfernt; im oberen rechten Kastenbereich wird zusätzlich das Stereotyp bzw. die Vererbung <code>AtpDefinition</code> neben <code>ARElement</code> ausgewiesen.\n</li><li><code>SwDataDefProps</code>: Paketpräfix <code>DataDefProperties::</code> im Klassennamen entfernt.\n</li></ul>"}, {"from": "FIG-e643584321097067", "to": "FIG-f296eb605c1e4cad", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>SwDataDefProps</code>: Attribut <code>mcFunction :Identifier [0..1]</code> entfernt.\n</li><li><code>SwDataDefProps</code>: Attribut <code>stepSize :Float [0..1]</code> hinzugefügt.\n</li></ul>"}]};
